function validate([chars]) {
  if (chars.length < 1 || chars.length > 2000) return 'chars needs 1 to 2000 characters.';
  for (const c of chars) {
    if (typeof c !== 'string' || c.length !== 1) return 'Each entry must be a single character.';
    const code = c.charCodeAt(0);
    if (code < 33 || code > 126) return 'Each character must be a letter, a digit or a visible ASCII symbol.';
  }
  return null;
}

