function compress(chars) {
  let write = 0;
  let read = 0;

  while (read < chars.length) {
    const current = chars[read];
    let count = 0;
    while (read < chars.length && chars[read] === current) {
      read++;
      count++;
    }
    chars[write] = current;
    write++;
    if (count > 1) {
      for (const digit of String(count)) {
        chars[write] = digit;
        write++;
      }
    }
  }
  return write;
}

