function compress(chars) {
  const groups = [];
  for (const c of chars) {
    const last = groups[groups.length - 1];
    if (last && last.c === c) last.n += 1;
    else groups.push({ c, n: 1 });
  }
  let text = '';
  for (const g of groups) text += g.n === 1 ? g.c : g.c + g.n;
  for (let i = 0; i < text.length; i++) chars[i] = text[i];
  return text.length;
}

