function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pools = ['ab', 'abc', 'aAbB', '0123456789', 'xy19#@!', 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+[]{};:,.<>/?~'];
  const pool = pools[int(0, pools.length - 1)];
  const chars = [];
  if (size === 'large') {
    while (chars.length < 2000) {
      const roll = rand();
      const run = roll < 0.5 ? int(1, 3) : roll < 0.85 ? int(4, 30) : roll < 0.97 ? int(31, 200) : int(201, 1200);
      const c = pool[int(0, pool.length - 1)];
      for (let k = 0; k < run && chars.length < 2000; k++) chars.push(c);
    }
    return [chars];
  }
  const target = int(1, 14);
  while (chars.length < target) {
    const run = rand() < 0.15 ? int(9, 13) : int(1, 4);
    const c = pool[int(0, pool.length - 1)];
    for (let k = 0; k < run && chars.length < target + 6; k++) chars.push(c);
  }
  return [chars];
}
